/**
 * Unit tests for StdDateFormat#isLenient
 */
public class StdDateFormat_isLenient_TriageGen0Test {







    @Test
    public void testIsLenientWithConstructor() {
        // Using the constructor with TimeZone and Locale to ensure initialization
        StdDateFormat df = new StdDateFormat(TimeZone.getDefault(), Locale.US);
        // Default should still be true
        assertTrue("isLenient should be true after constructor initialization", df.isLenient());

        df.setLenient(false);
        assertFalse("isLenient should be false after explicit set", df.isLenient());
    }


}

package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat#isLenient
 */
public class StdDateFormat_isLenient_TriageGen0Test {









    @Test
    public void testIsLenientAfterClone() {
        StdDateFormat df = new StdDateFormat();
        df.setLenient(false);

        StdDateFormat cloned = df.clone();
        assertFalse("Cloned object should preserve the lenient state", cloned.isLenient());

        cloned.setLenient(true);
        assertTrue("Cloned object modification should not affect original", df.isLenient());
    }
}
